 ice:      {name:'빙결',c:'#6cc4ec',fx:['ice/freeze','ice/frost-nova','ice/ice-shatter','ice/snowflake-burst']},
 water:    {name:'물',  c:'#6aa8f0',fx:['water/geyser','water/wave-crash','water/splash']},
 lightning:{name:'번개',c:'#ffc94a',fx:['lightning/zap-hit','lightning/thunderclap','lightning/lightning-strike']},
 earth:    {name:'대지',c:'#7cc46a',fx:['nature/quake']},
 poison:   {name:'독',  c:'#b89aff',fx:['nature/acid-splash']},
 blast:    {name:'폭발',c:'#ff9cc8',fx:['explosions/firework-burst','explosions/grenade']},
