const CHART={fire:{weak:['water','ice'],res:'fire'},ice:{weak:['fire','blast'],res:'ice'},water:{weak:['lightning','poison'],res:'water'},
 lightning:{weak:['earth','shadow'],res:'lightning'},earth:{weak:['water','ice'],res:'earth'},poison:{weak:['fire','holy'],res:'poison'},
 blast:{weak:['ice','water'],res:'blast'},holy:{weak:['shadow','arcane'],res:'holy'},arcane:{weak:['lightning','blast'],res:'arcane'},
 shadow:{weak:['holy','lightning'],res:'shadow'}};
/* 속성마다 보여 줄 몬스터 모습 · 설명 · 전투에서 쓰는 대표 이펙트 */
const SPRITE={fire:'불꽃 정령',ice:'서리 결정',water:'심해 해파리',lightning:'뇌운',earth:'이끼 골렘',poison:'독 슬라임',blast:'봄버',holy:'세라핌',arcane:'떠도는 눈',shadow:'망령'};
const LORE={
 fire:'살아 있는 불꽃. 같은 불은 장작일 뿐이지만, 물을 뒤집어쓰거나 냉기에 닿으면 불씨가 꺼져 간다.',
 ice:'공중을 떠도는 얼음 결정. 냉기는 몸집을 키울 뿐이고, 열과 폭발의 충격에 금이 간다.',
 water:'파도와 함께 사는 생물이라 물살엔 끄떡없다. 전류가 몸 전체로 퍼지고, 산성에 물이 오염되면 약해진다.',
 lightning:'전기를 머금은 먹구름. 번개는 그대로 빨아들이지만, 땅이 전기를 끌어내리고 저주가 빛을 삼킨다.',
 earth:'이끼 덮인 바위 몸은 땅울림에 흔들리지 않는다. 물이 스며들고 얼어붙으면 바위에 균열이 간다.',
 poison:'독액으로 된 몸. 같은 산성은 스며들 뿐이지만, 불에 증발하고 정화의 빛에 독기가 씻겨 나간다.',
 blast:'심지에 불이 붙은 채 걸어 다니는 폭탄. 폭발엔 익숙하지만, 심지가 얼거나 물에 젖으면 꼼짝 못 한다.',
 holy:'후광을 두른 날개 달린 눈. 신성한 일격은 축복으로 받아들이지만, 저주와 마력의 혼돈에 빛이 흐트러진다.',
 arcane:'마력을 빨아들이는 눈알. 비전 탄환은 흡수하지만 천둥소리와 눈부신 섬광에는 무방비다.',
 shadow:'그림자로 짜인 누더기 영혼. 생명력을 빼앗는 기술은 되레 먹이가 되고, 성스러운 빛과 전격에 형체가 찢긴다.'};
const HIT={fire:'fire/flame-pillar',ice:'ice/freeze',water:'water/geyser',lightning:'lightning/lightning-strike',earth:'nature/quake',
 poison:'nature/acid-splash',blast:'explosions/grenade',holy:'holy/holy-pillar',arcane:'arcane/mana-burst',shadow:'shadow/curse'};
const FXK={'fire/fire-ring':'파이어 링','ice/freeze':'빙결','nature/acid-splash':'산성 폭발','lightning/zap-hit':'전격',
 'explosions/firework-burst':'불꽃놀이','nature/quake':'지진','holy/holy-pillar':'성광 기둥','arcane/mana-burst':'마나 폭발',
 'explosions/grenade':'수류탄','lightning/thunderclap':'천둥','shadow/curse':'저주','arcane/arcane-missiles':'비전 탄환',
 'ice/frost-nova':'프로스트 노바','holy/smite':'신성 강타','fire/flame-pillar':'화염 기둥','fire/meteor':'메테오',
 'water/geyser':'간헐천','ice/ice-shatter':'얼음 파쇄','lightning/lightning-strike':'낙뢰','holy/heal-aoe':'치유의 고리',
 'shadow/life-steal':'생명력 흡수','water/wave-crash':'해일','water/splash':'물보라','ice/snowflake-burst':'눈꽃 폭발'};
const MON_BY={};MON.forEach(m=>{MON_BY[m.name]=m});
const monOf=el=>MON_BY[SPRITE[el]]||MON[0];
const affOf=(atk,mon)=>!CHART[mon]||!atk?1:CHART[mon].weak.indexOf(atk)>=0?2:CHART[mon].res===atk?.5:1;
// 속성 표시: 속성 색의 작은 네모 (그림 아이콘 없이)
const iconImg=(el,cls)=>ELEM[el]?'<i class="'+(cls||'afx-ic')+'" style="background:'+ELEM[el].c+'" aria-hidden="true"></i>':'';
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]);

